from __future__ import annotations

import os
import subprocess
import threading
from pathlib import Path

from .app import run_server

SQUID_CONF = (
    "# generated by the BixBench3 network gateway\n"
    "external_acl_type bixbench3_allowlist ttl=5 "
    "children-max=8 children-startup=1 %URI "
    "/usr/local/bin/bixbench3-acl-helper\n"
    "acl bixbench3_allow external bixbench3_allowlist\n"
    "http_access allow bixbench3_allow\n"
    "http_access deny all\n"
    "http_port 3128\n"
    "access_log stdio:/var/log/squid/access.log\n"
    "cache deny all\n"
)


def main() -> int:
    squid_dir = Path(
        os.environ.get(
            "BIXBENCH3_SQUID_CONFIG_DIR",
            "/etc/squid",
        )
    )
    squid_log_dir = Path(
        os.environ.get(
            "BIXBENCH3_SQUID_LOG_DIR",
            "/var/log/squid",
        )
    )
    squid_dir.mkdir(parents=True, exist_ok=True)
    squid_log_dir.mkdir(parents=True, exist_ok=True)
    squid_config = squid_dir / "squid.conf"
    squid_config.write_text(SQUID_CONF, encoding="utf-8")
    log_dir = Path(
        os.environ.get(
            "BIXBENCH3_BROKER_LOG_DIR",
            "/tmp/bixbench3-broker-logs",
        )
    )
    cache_dir = Path(
        os.environ.get(
            "BIXBENCH3_BROKER_CACHE_DIR",
            "/tmp/bixbench3-broker-cache",
        )
    )
    approved_web_dir = Path(
        os.environ.get(
            "BIXBENCH3_APPROVED_WEB_DIR",
            "/workspace/approved_web",
        )
    )
    for writable_dir in (log_dir, cache_dir, approved_web_dir):
        writable_dir.mkdir(parents=True, exist_ok=True)
        subprocess.run(
            ["chmod", "-R", "a+rwX", str(writable_dir)],
            check=False,
        )
    server_thread = threading.Thread(target=run_server, daemon=True)
    server_thread.start()
    supervisor_log = log_dir / "squid_supervisor.log"
    with supervisor_log.open("a", encoding="utf-8") as log:
        parse = subprocess.run(
            ["squid", "-k", "parse", "-f", str(squid_config)],
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
            check=False,
        )
        log.write(f"squid parse exited with status {parse.returncode}\n")
        log.flush()
        if parse.returncode != 0:
            return parse.returncode
        process = subprocess.Popen(
            ["squid", "-N", "-d", "1", "-f", str(squid_config)],
            stdout=log,
            stderr=subprocess.STDOUT,
            text=True,
        )
        status = process.wait()
        log.write(f"squid exited with status {status}\n")
        return status


if __name__ == "__main__":
    raise SystemExit(main())
